    cards: [
      { q: "【徴収・第51回】事業主が提出した確定保険料申告書の記載に誤りがあり、労働保険料の額が不足していた場合、所轄都道府県労働局歳入徴収官は労働保険料の額を決定し、これを事業主に通知する。このとき事業主は、通知を受けた日の翌日から起算して30日以内にその不足額を納付しなければならない。", a: "× 認定決定による確定保険料の不足額は、[[通知を受けた日から15日以内]]に納付しなければならない。「30日以内」が誤り。", p: "確定保険料の認定決定の不足額は、通知を受けた日から15日以内に納付。" },
      { q: "【徴収・第49回】認定決定された確定保険料に対しては追徴金が徴収されるが、滞納した場合には、この追徴金を含めた額に対して延滞金が徴収される。", a: "× 延滞金は[[労働保険料の納付遅延に対して徴収されるもの]]で、[[追徴金には延滞金は徴収されない]]。「追徴金を含めた額に対して延滞金」が誤り。", p: "延滞金は労働保険料に対するもの。追徴金には延滞金は徴収されない。" },
      { q: "【徴収・第48回】事業主は、正当な理由がないと認められるにもかかわらず、印紙保険料の納付を怠ったときは、認定決定された印紙保険料の額（その額に1000円未満の端数があるときは、その端数は、切り捨てる）の100分の10に相当する追徴金を徴収される。", a: "× 印紙保険料の納付を怠った場合の追徴金は[[100分の25]]。「100分の10」が誤り（確定保険料の追徴金が100分の10、印紙保険料が100分の25）。", p: "印紙保険料の追徴金は100分の25（確定保険料は100分の10）。" },
      { q: "【徴収・第51回】労働保険徴収法第27条第1項の督促に関し、納付しない場合の具体的な例には、保険年度の6月1日を起算日として40日以内又は保険関係成立の日の翌日を起算日として50日以内に（延納する場合には各々定められた納期限までに）納付すべき概算保険料の完納がない場合がある。", a: "○ 概算保険料の納期限は[[保険年度の6月1日から40日以内、保険年度の中途に保険関係が成立した場合は成立日（の翌日を起算）から50日以内]]。これらの完納がない場合は督促の対象になる。", p: "概算保険料の納期限＝6月1日から40日以内／中途成立は成立日から50日以内。" },
      { q: "【徴収・第51回】事業主は、既に納付した概算保険料の額のうち確定保険料の額を超える額（超過額）の還付を請求できるが、その際、労働保険料還付請求書を所轄都道府県労働局歳入徴収官に提出しなければならない。", a: "○ 概算保険料が確定保険料を超える超過額は、原則として次の保険料に充当されるが、事業主は還付を請求でき、その際は[[労働保険料還付請求書を所轄都道府県労働局歳入徴収官に提出]]する。", p: "概算が確定を超える超過額は還付請求でき、還付請求書を歳入徴収官に提出。" },
      { q: "【徴収・第51回】事業主は、既に納付した概算保険料の額と確定保険料の額が同一であり過不足がないときは、確定保険料申告書を所轄都道府県労働局歳入徴収官に提出するに当たって、日本銀行、年金事務所又は労働基準監督署を経由して提出できる。", a: "○ 過不足がなく納付を伴わない確定保険料申告書は、[[日本銀行・年金事務所・労働基準監督署を経由して提出できる]]（納付を伴う場合の経由先とは扱いが異なる）。", p: "過不足なしの確定保険料申告書は、日本銀行・年金事務所・労基署を経由して提出できる。" },
    ],
