    note: '時間外・休日・深夜・変形の制限と軽易業務転換・産前産後休業は妊産婦（や妊娠中）が対象で、原則として本人の「請求」が要件。育児時間・生理日休暇は女性労働者一般が対象（生理日休暇の請求に医師の診断書は不要）。※試験実施団体とは関係ありません。以下は過去問の肢を逐語掲載し、現行法令で○×を確定したものです。',
    cards: [
      { q: '【労基・第49回】使用者は、すべての妊産婦について、時間外労働、休日労働又は深夜業をさせてはならない。', a: '× 時間外・休日・深夜業をさせてはならないのは、妊産婦が[[請求した場合]]に限られる（66条）。「すべての妊産婦について」一律ではない。', p: '妊産婦の時間外・休日・深夜の制限は「請求した場合」に限る。' },
      { q: '【労基・第49回】使用者は、生理日の就業が著しく困難な女性が休暇を請求したときは、その者を生理日に就業させてはならないが、請求にあたっては医師の診断書が必要とされている。', a: '× 生理日の就業困難による休暇の請求に、[[医師の診断書は必要とされていない]]。設問後段が誤り。', p: '生理日休暇の請求に医師の診断書は不要。' },
      { q: '【労基・第45回】労働基準法では、「妊産婦」は、「妊娠中の女性及び産後4か月を経過しない女性」とされている。', a: '× 妊産婦は「妊娠中の女性及び[[産後1年]]を経過しない女性」（64条の3）。「産後4か月」は誤り。', p: '妊産婦＝妊娠中＋産後1年を経過しない女性。' },
      { q: '【労基・第53回】使用者は、産後8週間（女性が請求した場合において、その者について医師が支障がないと認めた業務に就かせる場合は6週間）を経過しない女性を就業させてはならないが、出産当日は、産前6週間に含まれる。', a: '○ 産後[[8週間]]（請求＋医師が支障なしと認めた業務なら6週間）を経過しない女性は就業禁止。[[出産当日は産前6週間]]に含まれる。', p: '産後8週禁止（請求＋医師で6週可）・出産当日は産前に算入。' },
      { q: '【労基・第53回】6週間（多胎妊娠の場合にあっては、14週間）以内に出産する予定の女性労働者については、当該女性労働者の請求が産前の休業の条件となっているので、当該女性労働者の請求がなければ、労働基準法第65条第1項による就業禁止に該当しない。', a: '○ 産前休業（6週・多胎14週）は[[女性の請求が条件]]であり、請求がなければ65条1項の[[就業禁止に該当しない]]（産後と異なり就業させても違反でない）。', p: '産前休業は請求が条件（請求なければ就業禁止に当たらない）。' },
      { q: '【労基・第53回】労働基準法第32条又は第40条に定める労働時間の規定は、事業の種類にかかわらず監督又は管理の地位にある者には適用されないが、当該者が妊産婦であって、前記の労働時間に関する規定を適用するよう当該者から請求があった場合は、当該請求のあった規定については適用される。', a: '× [[管理監督者]]は労働時間等の規定が適用除外であり、妊産婦であっても請求により労働時間規定が適用されることはない。設問は誤り。', p: '管理監督者は妊産婦でも労働時間規定の適用除外のまま。' },
      { q: '【労基・第55回】女性労働者が妊娠中絶を行った場合、産前6週間の休業の問題は発生しないが、妊娠4か月（1か月28日として計算する。）以後行った場合には、産後の休業について定めた労働基準法第65条第2項の適用がある。', a: '○ 妊娠[[4か月以後]]の中絶（流産・死産を含む）は「出産」に当たり、[[産後休業（65条2項）の適用がある]]。', p: '妊娠4か月以後の中絶は産後休業の適用あり。' },
    ],
