    note: '移送費の額は「最も経済的な通常の経路及び方法」で算定（通勤の定義の「合理的な経路及び方法」とは別概念）。通勤災害の一部負担金200円は初回の休業給付から控除。待期中の所得保障は労災の業務災害だけ（初日〜3日目は事業主が平均賃金60％を休業補償）。※試験実施団体とは関係ありません。以下は過去問の肢を逐語掲載し、現行法令で○×を確定したものです。',
    cards: [
      { q: '【健保・第52回】労災保険法に基づく休業補償給付を受給している健康保険の被保険者が、さらに業務外の事由による傷病によって労務不能の状態になった場合、休業補償給付が支給され、傷病手当金が支給されることはない。', a: '○ 労災の[[休業補償給付を受給している間]]は、業務外の傷病による[[傷病手当金は支給されない]]（労務不能の状態を二重に評価しない）。', p: '休業補償給付を受けている間は傷病手当金は支給されない。' },
      { q: '【健保・第54回】被保険者又は被扶養者の業務災害については健康保険法に基づく保険給付の対象外であり、労災保険法に規定する業務災害に係る請求が行われている場合には、健康保険の保険給付の申請はできない。', a: '× 健保は[[業務災害以外]]を対象とするが、当該事案が業務災害でないと判断されれば健保の保険給付を申請できる。労災の請求がされていることだけで健保の[[申請ができないわけではない]]。', p: '労災の請求中でも、業務災害でなければ健保の申請はできる。' },
      { q: '【健保・第46回】被保険者が通勤途上負傷し、労災保険の保険給付を受けることができるときは、その負傷について健康保険からの保険給付は行われず、その者が勤務する事業所が労災保険の任意適用事業所で労災保険に未加入であった場合にも、同様に健康保険からの保険給付は行われない。', a: '× 労災の給付を[[受けることができるとき]]は健保の給付は行われないが、労災の任意適用事業所で[[未加入のため労災給付を受けられない]]場合は、[[健康保険の保険給付が行われる]]。後段は誤り。', p: '労災未加入で労災給付を受けられないなら健保の給付が行われる。' },
      { q: '【健保・第46回】妊娠4か月を過ぎてから業務上の事故により流産し、労災保険法の療養補償給付を受けた場合、健康保険から出産育児一時金の支給は行われない。', a: '× 出産育児一時金は業務上・業務外を問わず[[妊娠4か月以後の出産（流産・死産を含む）に支給]]される。労災に出産に対する給付はなく、[[出産育児一時金は支給される]]。', p: '妊娠4か月以後の流産でも出産育児一時金は支給される（業務上でも）。' },
      { q: '【健保・第55回】被保険者（任意継続被保険者を除く。）が業務外の疾病により労務に服することができないときは、その労務に服することができなくなった日から起算して4日を経過した日から労務に服することができない期間、傷病手当金を支給する。', a: '× 傷病手当金は、労務不能となった日から[[3日間の待期]]を経て、[[4日目から]]支給する。「4日を経過した日（＝5日目）から」は誤り。', p: '傷病手当金は待期3日を経て4日目から支給（4日経過日からではない）。' },
    ],
