    title: '労働保険事務組合（徴収）',
    tagline: '中小事業主が労働保険事務を委託する団体。委託できる規模は業種別（金融保険不動産小売50人以下／卸売サービス100人以下／その他300人以下）。認可は厚労大臣（委任で都道府県労働局長）。',
