    tagline: '傷病手当金・出産手当金は喪失時に受けていれば継続（傷病は通算1年6か月の範囲）。出産育児一時金は喪失後6か月以内の出産。埋葬料は喪失後3か月以内の死亡。1年以上の被保険者期間は埋葬料だけ不要。',
