    note: '受給権者が現況を知らせる書類は提出時期が決まっている。公的年金の現況届は毎年「誕生月の末日まで」（マイナンバー収録者は原則省略）。障害年金の障害状態確認届（診断書）は、厚生労働大臣が指定した年（1〜5年ごと）の誕生月末日まで提出し、診断書は「提出期限前3か月以内」の障害の状態（現症）を記載する（令和元年8月生月者分から作成期間が3か月に拡大）。20歳前傷病による障害基礎年金の障害状態確認届は、従来の7月末から「誕生月末日」に変更された。20歳前障害基礎年金の所得状況届は、令和元年度からマイナンバー連携により原則送付・提出不要（所得確認ができない場合のみ提出）。労災年金（障害・傷病・遺族の各補償等年金）の定期報告（現状報告書）は毎年1回、受給権者の生年月日の区分で指定された月に所轄労働基準監督署長へ。いずれも期限までに出さないと年金の支払が一時差し止められることがある。',
