    note: '健康保険の保険者は全国健康保険協会と健康保険組合だが、協会管掌健康保険の適用・徴収など厚生労働大臣の権限に係る事務は日本年金機構に行わせる。「権限に係る事務の委任」は、任意適用の承認・資格の確認・標準報酬月額や標準賞与額の決定・保険料の賦課や督促・滞納処分など、処分（公権力の行使）を含む事務を機構が行うもの（質問・検査等の権限は厚生労働大臣が自ら行うことも妨げない）。「事務の委託」は、価額の決定・情報提供・資料提供・保険料徴収に係る事務などで、条文上「当該承認を除く」「当該決定を除く」と、処分・判断そのものは除いた付随事務を機構に委ねるもの。さらに、滞納処分等の権限や機構が行う収納の仕組み、国税滞納処分の例による処分について財務大臣（国税庁長官）への権限委任もある。',
