    id: 'kokunen-rorei-gaku',
    title: '老齢基礎年金の額',
    tagline: '保険料納付済期間480月で満額。免除期間は国庫負担1/2化（H21.4〜）後、全額免除＝1/2、3/4免除＝5/8、半額免除＝6/8、1/4免除＝7/8が反映。学生納付特例・納付猶予は額に反映されない（追納すれば反映）。',
