    title: '第3号被保険者の届出と特例',
    tagline: '第3号被保険者の資格取得・喪失・種別変更の届出は、配偶者（第2号）の事業主等を経由して行う。届出が2年以上遅れると原則前々月までしか算入されないが、やむを得ない事由があれば特例届出で2年より前も納付済期間に算入。',
