    note: '第3号被保険者（第2号被保険者に扶養される配偶者）の資格の取得・喪失・種別変更の届出は、その配偶者である第2号被保険者の事業主等を経由して行う（平成26年12月から事業主経由方式）。届出が2年以上遅れた場合、原則として届出日の前々月（直近2年）分までしか保険料納付済期間に算入されないが、届出が遅れたことについてやむを得ない事由があると認められれば、特例届出により2年より前の期間もさかのぼって納付済期間に算入される。【2方向の整理】結婚等で第1号から第3号になったのに種別変更届を出していなかった期間は、実態が第3号なので、第3号該当届を出せば保険料納付済期間として扱われる。一方、離婚や配偶者の退職等で第3号から第1号になったのに届出をしていなかった期間は「不整合期間」（実態は第1号で本来保険料納付義務がある）で、訂正時に徴収の時効（2年）が過ぎている部分は「時効消滅不整合期間」となる。時効消滅不整合期間は、特定期間該当届を出すと「特定期間」となり、学生納付特例期間とみなされて受給資格期間には算入されるが年金額には反映されない。さらに平成27年4月から平成30年3月までの間に特定保険料（最大10年分）を納付すれば、保険料納付済期間にすることができた。',
