    note: '会社分割（吸収分割・新設分割）に伴う労働契約の承継のルール。①分割される事業に「主として従事する労働者」は、分割契約等にその労働契約を承継する旨の定めがあれば当然に承継会社等に承継され、異議を申し出ることはできない。承継の定めがない場合は、労働者が異議を申し出ることで承継される。②「主として従事しない労働者」は、承継の定めがあっても異議を申し出れば承継から除外され、元の分割会社に残る。会社は、分割に当たり労働者へ書面で通知し、労働者の理解と協力を得るよう努める（いわゆる5条協議・7条措置）。承継される労働契約は、労働条件もそのまま引き継がれる。',
