    note: '労働基準法は、労働者の業務上の負傷・疾病・死亡について、使用者の無過失の災害補償責任（療養補償、休業補償＝平均賃金の100分の60、障害補償、遺族補償、葬祭料、打切補償）を定める。労働者災害補償保険法その他の法令により労基法の災害補償に相当する給付が行われるべきものである場合、使用者はその限度で労基法上の補償の責を免れる（実務上は労災保険が補償を担う）。打切補償は、療養補償を受ける労働者が療養開始後3年を経過しても傷病が治らない場合に、平均賃金の1,200日分を支払えば以後の補償を行わなくてよいとするもの（解雇制限も解除される）。使用者は、同一の事由については災害補償を行った価額の限度で民法による損害賠償の責を免れる。',
