    tagline: '建設業・造船業の特定元方事業者は、同一場所で下請の労働者も含めて作業させる場合、統括安全衛生責任者を選任し、協議組織の設置・作業間の連絡調整・作業場所の巡視（毎作業日）等を行う。下請側は安全衛生責任者を選任。',
    subjects: ['anei'],
