    note: '教育訓練支援給付金は、専門実践教育訓練を受ける45歳未満の離職者（受給資格者）が、訓練期間中に基本手当の支給を受けることができない場合に支給される暫定措置で、額は基本手当日額の60%（令和7年4月1日以降の受講開始分から、従来の80%→60%に引下げ）。令和9年3月31日までの時限措置。令和7年10月からは新たに「教育訓練休暇給付金」が創設され、在職中の被保険者が無給の教育訓練休暇（30日以上等）を取得して教育訓練を受ける場合に、基本手当日額の45〜80%（被保険者期間に応じる）を支給する。いずれも雇用保険による学び直し（リスキリング）支援の給付。',
