    note: '安衛法65条＝事業者は、有害な業務を行う屋内作業場その他の作業場で政令で定めるものについて、必要な作業環境測定を行い、その結果を記録しておかなければならない。測定は厚生労働大臣の定める作業環境測定基準に従う。指定作業場（粉じん・特定化学物質・石綿・鉛・有機溶剤・放射性物質等に係るもの）の測定は、作業環境測定士又は作業環境測定機関が行う。65条の2＝事業者は、測定結果の評価（作業環境評価基準に基づき第1管理区分〔適切〕・第2管理区分・第3管理区分〔要改善〕に区分）に基づいて、労働者の健康を保持するため必要があると認められるときは、施設又は設備の設置・整備、健康診断の実施その他の適切な措置を講じなければならない。評価の結果も記録する。',
